package com.powerliq.marketdata;
import com.fasterxml.jackson.databind.*;import com.powerliq.events.*;import java.net.URI;import java.time.Duration;import org.slf4j.*;import org.springframework.beans.factory.annotation.Value;import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;import org.springframework.context.annotation.*;import org.springframework.scheduling.annotation.Scheduled;import org.springframework.stereotype.Component;import software.amazon.awssdk.auth.credentials.AwsBasicCredentials;import software.amazon.awssdk.auth.credentials.DefaultCredentialsProvider;import software.amazon.awssdk.auth.credentials.StaticCredentialsProvider;import software.amazon.awssdk.regions.Region;import software.amazon.awssdk.services.sqs.SqsClient;import software.amazon.awssdk.services.sqs.model.*;
@Component @ConditionalOnProperty(name="powerliq.events.consumer.enabled",havingValue="true")
public class MarketPriceQueueConsumer{
 private static final Logger LOG=LoggerFactory.getLogger(MarketPriceQueueConsumer.class);private final SqsClient sqs;private final ObjectMapper json;private final MarketDataService service;private final String queueUrl;private final JavaType eventType;private final int batchSize,waitSeconds,visibilitySeconds;
 public MarketPriceQueueConsumer(SqsClient sqs,ObjectMapper json,MarketDataService service,@Value("${powerliq.events.queue-url}")String queueUrl,@Value("${powerliq.events.consumer-batch-size:10}")int batchSize,@Value("${powerliq.events.wait-seconds:10}")int waitSeconds,@Value("${powerliq.events.visibility-seconds:30}")int visibilitySeconds){if(batchSize<1||batchSize>10||waitSeconds<0||waitSeconds>20||visibilitySeconds<1||visibilitySeconds>43200)throw new IllegalArgumentException("Event consumer bounds are invalid");this.sqs=sqs;this.json=json;this.service=service;this.queueUrl=queueUrl;this.batchSize=batchSize;this.waitSeconds=waitSeconds;this.visibilitySeconds=visibilitySeconds;eventType=json.getTypeFactory().constructParametricType(EventEnvelope.class,MarketPriceRevisionV1.class);}
 @Scheduled(fixedDelayString="${powerliq.events.consumer-delay:1000}")public void poll(){ReceiveMessageResponse response=sqs.receiveMessage(r->r.queueUrl(queueUrl).maxNumberOfMessages(batchSize).waitTimeSeconds(waitSeconds).visibilityTimeout(visibilitySeconds));for(Message message:response.messages())process(message);}
 private void process(Message message){try{JsonNode detail=json.readTree(message.body()).required("detail");EventEnvelope<MarketPriceRevisionV1> event=json.readValue(detail.traverse(json),eventType);service.consume(event);sqs.deleteMessage(r->r.queueUrl(queueUrl).receiptHandle(message.receiptHandle()));}catch(Exception e){LOG.error("Market-price event processing failed messageId={}",message.messageId(),e);}}
 @Configuration @ConditionalOnProperty(name="powerliq.events.consumer.enabled",havingValue="true")static class ClientConfiguration{@Bean SqsClient sqsClient(@Value("${powerliq.aws.region:eu-west-2}")String region,@Value("${powerliq.events.endpoint:}")String endpoint){var builder=SqsClient.builder().region(Region.of(region)).credentialsProvider(DefaultCredentialsProvider.create()).overrideConfiguration(c->c.apiCallTimeout(Duration.ofSeconds(15)).apiCallAttemptTimeout(Duration.ofSeconds(12)));if(!endpoint.isBlank())builder.endpointOverride(URI.create(endpoint)).credentialsProvider(StaticCredentialsProvider.create(AwsBasicCredentials.create("local","local")));return builder.build();}}
}
